/**
 * emit to subscription queries of type FindWorkOrder,
 * but only if the id matches
 *
 * @param		entity	WorkOrder
 */
	protected void emitFindWorkOrder( WorkOrder entity ) {
		LOGGER.info("handling emitFindWorkOrder" );
		
	    queryUpdateEmitter.emit(FindWorkOrderQuery.class,
	                            query -> query.getFilter().getWorkOrderId().equals(entity.getWorkOrderId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllWorkOrder
	 * 
	 * @param		entity	WorkOrder
	 */
	protected void emitFindAllWorkOrder( WorkOrder entity ) {
		LOGGER.info("handling emitFindAllWorkOrder" );
		
	    queryUpdateEmitter.emit(FindAllWorkOrderQuery.class,
	                            query -> true,
	                            entity);
	}

